    assert_eq!(frame.memory_stats().live_bytes, before_stats.live_bytes);
    assert_eq!(frame.view().clips.len(), before_clips);
    assert_eq!(
        frame.view().clip(child_full).unwrap().user_inverse,
        before_inverse
    );
}

